        params = []
        if resource_type: params.append(f"resource_type={resource_type}")
        if resource_id: params.append(f"resource_id={resource_id}")
        qs = "&".join(params)
        path = f"/changes/history?{qs}" if qs else "/changes/history"
        return self._request("GET", path)


